use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\DB;
Schema::create('profiles', function ($t) {
    $t->id();
    $t->string('full_name');
});
DB::table('profiles')->insert(['full_name' => 'Ada']);
Schema::table('profiles', function ($t) {
    $t->string('display_name')->nullable();
});
DB::table('profiles')->update(['display_name' => DB::raw('full_name')]);
$row = DB::table('profiles')->first();
echo $row->full_name.':'.$row->display_name;
